declare namespace SigApi {
    interface KeyValueCache<K, V> {
        /**
         * Map of cached values
         */
        map: Map<K, V>
        /**
         * Returns cached value or calls fetchFunction.
         * @param {any} key 
         * @param {Function} fetchFunction {Function} ({key: K}): V
         * @returns {any}
         */
        getValue(key: K, fetchFunction: (key: K) => V): V
        /**
         * Returns cached value or calls async fetchFunction.
         * Does not cache rejected results.
         * @param {any} key 
         * @param {Function} fetchFunction {Function} ({key: K}): V
         * @returns {Promise<any>}
         */
        getValueAsync(key: K, fetchFunction: (key: K) => V): V
    }
}
